// clang-format on
static_assert(W::measured(windows), "every window row hashes to its FNV-1a and its fixups lie inside it");
constexpr bool spans_in_windows() {
    const unsigned w[count] = {window_leaf_yaw_pitch, window_leaf_roll_yaw, window_leaf_roll_pitch, window_loop_continue};
    for (unsigned i = 0; i < count; ++i) {
        const W::Window& win = windows[w[i]];
        if (spans[i].rva < win.rva || spans[i].rva + spans[i].length > win.rva + win.length) return false;
        for (unsigned k = 0; k < spans[i].length; ++k)
            if (win.bytes[spans[i].rva - win.rva + k] != spans[i].bytes[k]) return false;
    }
    return true;
}
static_assert(spans_in_windows(), "each claimed span lies in its window with the same bytes");
